@sig trait ThreatEvidenceQualifier_Api {
  def id: Art.BridgeId
  def threatObservation_Id : Art.PortId
  def evidenceAssessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var evidenceAssessment: Frigate_Threat_Egress_Supervisor.EvidenceAssessment.Type = $

  def put_evidenceAssessment(value : Frigate_Threat_Egress_Supervisor.EvidenceAssessment.Type) : Unit = {
    Contract(
      Modifies(evidenceAssessment),
      Ensures(
        evidenceAssessment == value
      )
    )
    Spec {
      evidenceAssessment = value
    }

    Art.putValue(evidenceAssessment_Id, Frigate_Threat_Egress_Supervisor.EvidenceAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ThreatEvidenceQualifier_Initialization_Api (
  val id: Art.BridgeId,
  val threatObservation_Id : Art.PortId,
  val evidenceAssessment_Id : Art.PortId) extends ThreatEvidenceQualifier_Api

@datatype class ThreatEvidenceQualifier_Operational_Api (
  val id: Art.BridgeId,
  val threatObservation_Id : Art.PortId,
  val evidenceAssessment_Id : Art.PortId) extends ThreatEvidenceQualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var threatObservation: Frigate_Threat_Egress_Supervisor.ThreatObservation = $

  def get_threatObservation() : Option[Frigate_Threat_Egress_Supervisor.ThreatObservation] = {
    Contract(
      Ensures(
        Res == Some(threatObservation)
      )
    )
    val value : Option[Frigate_Threat_Egress_Supervisor.ThreatObservation] = Art.getValue(threatObservation_Id) match {
      case Some(Frigate_Threat_Egress_Supervisor.ThreatObservation_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port threatObservation.  Expecting 'Frigate_Threat_Egress_Supervisor.ThreatObservation_Payload' but received ${v}")
        None[Frigate_Threat_Egress_Supervisor.ThreatObservation]()
      case _ => None[Frigate_Threat_Egress_Supervisor.ThreatObservation]()
    }
    return value
  }
}
